#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <queue>
using namespace std;

int main() {
    vector<string> category = {"A","A","B","A","B"};
    vector<int> mature = {1,3,2,9,8};
    vector<double> target = {1,0,1,1,0};
    int today = 5;
    double prior = 0.4, lambda = 2;
    map<string,int> count;
    map<string,double> sum;
    for(int i=0;i<int(category.size());i++){
        if(mature[i]>today)continue;
        count[category[i]]++;
        sum[category[i]]+=target[i];
    }
    for(const string& name:{"A","B"}){
        double estimate=(sum[name]+lambda*prior)/(count[name]+lambda);
        cout<<name<<" "<<fixed<<setprecision(4)<<estimate<<"\n";
    }
    return 0;
}

