double soft(double value,double lambda){
    if(value>lambda)return value-lambda;
    if(value< -lambda)return value+lambda;
    return 0;
}
int main() {
    vector<double> x={-2,-1,0,1,2};
    vector<double> y={-3,-1,0,1,3};
    double xx=0,xy=0,lambda=0.1;
    for(int i=0;i<int(x.size());i++){xx+=x[i]*x[i];xy+=x[i]*y[i];}
    xx/=x.size();xy/=x.size();
    double beta=soft(xy,lambda)/xx;
    cout<<fixed<<setprecision(6)<<beta<<"\n";
    return 0;
}

