#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <queue>
using namespace std;

int main(){
    int n=4;
    vector<vector<int>> graph(n);
    vector<int> degree(n,0);
    vector<pair<int,int>> edges={{0,2},{1,2},{2,3}};
    for(const auto& edge:edges){
        graph[edge.first].push_back(edge.second);
        degree[edge.second]++;
    }
    queue<int> q;
    for(int i=0;i<n;i++)if(degree[i]==0)q.push(i);
    while(!q.empty()){
        int u=q.front();q.pop();
        cout<<u<<" ";
        for(int v:graph[u]){
            degree[v]--;
            if(degree[v]==0)q.push(v);
        }
    }
    cout<<"\n";
    return 0;
}

